NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Hosea'

CHAPTERS = {
    1: {
        1: 'Herran sana, joka tuli Hoosealle, Beerin pojalle, Juudan kuningasten Ussian, Jootamin, Aahaan ja Hiskian päivinä ja Israelin kuninkaan Jerobeamin, Jooaan pojan, päivinä.',
        2: 'Herran sanojen alku Hoosealle. Herra sanoi Hoosealle: "Mene, ota itsellesi haureellinen vaimo ja haureudesta syntyneet lapset, sillä maa on rikkomalla rikkonut avion luopumalla Herrasta."',
        3: 'Hän lähti ja otti Goomerin, Diblaimin tyttären. Tämä tuli raskaaksi ja synnytti hänelle pojan.',
        4: 'Herra sanoi hänelle: "Pane hänelle nimeksi Jisreel, sillä vähän aikaa vielä, ja kostan Jisreelin verivelat Jeehun suvulle ja teen lopun Israelin heimon kuningaskunnasta.',
        5: 'Sinä päivänä särjen Israelin jousen Jisreelin laaksossa."',
        6: 'Vaimo tuli jälleen raskaaksi ja synnytti tyttären, ja Herra sanoi Hoosealle: "Pane hänelle nimeksi Loo-Ruhama, sillä en enää tästedes armahda Israelin heimoa, niin että antaisin heille todella anteeksi.',
        7: 'Mutta Juudan heimoa armahdan: pelastan heidät Herran, heidän Jumalansa, toimesta, mutta en pelasta heitä jousella, miekalla enkä sodalla, en hevosilla enkä ratsumiehillä."',
        8: 'Kun vaimo oli vieroittanut Loo-Ruhaman, hän tuli raskaaksi ja synnytti pojan.',
        9: 'Herra sanoi: "Pane hänelle nimeksi Loo-Ammi, sillä te ette ole kansani, enkä minä ole teidän omanne.',
    },
    2: {
        1: "Mutta israelilaisten luku on oleva kuin meren hiekka, jota ei mitata eikä lueta. Siinä paikassa, jossa heille on sanottu: 'Te ette ole kansani', heille sanotaan: 'Elävän Jumalan lapset!'",
        2: 'Silloin Juudan miehet ja Israelin miehet kokoontuvat yhteen ja asettavat itselleen yhden Pään; ja he lähtevät siitä maasta liikkeelle, sillä suuri on Jisreelin päivä.',
        3: 'Sanokaa veljiänne Ammiksi ja sisarianne Ruhamaksi."',
        4: '"Käykää oikeutta äitinne kanssa, käykää oikeutta, sillä hän ei ole vaimoni, enkä minä ole hänen miehensä. Poistakoon hän haureutensa kasvoistaan ja aviorikoksensa rintojensa välistä,',
        5: 'etten riisu häntä alasti ja aseta häntä sellaiseksi, kuin hän oli syntymänsä päivänä, etten tee häntä erämaan kaltaiseksi ja saata häntä kuivan maan kaltaiseksi ja anna hänen kuolla janoon.',
        6: 'Mutta hänen lapsiaan en armahda, sillä he ovat haureuden lapsia.',
        7: "Sillä heidän äitinsä on harjoittanut haureutta. Se, josta he ovat siinneet, on häpeällisesti elänyt, ja hän on sanonut: 'Kuljen rakastajieni perässä, jotka antavat minulle leipäni ja veteni, villani ja pellavani, öljyni ja juomani.'",
        8: 'Sen tähden, katso, aitaan tiesi orjantappuroilla, ja muuraan muurin hänen eteensä, niin ettei hän löydä polkujaan.',
        9: "Hän ajaa takaa rakastajiaan, mutta ei saavuta heitä, ja etsii heitä, mutta ei löydä. Hän sanoo: 'Palaan entisen mieheni luo, sillä minulla oli paremmin silloin kuin nyt.'",
        10: 'Hän ei ole tiennyt, että minä olen hänelle antanut jyvät, rypälemehun ja öljyn, olen lisännyt hänelle paljon hopeaa ja myös kultaa, mitä he ovat käyttäneet Baalia varten.',
        11: 'Sen tähden otan takaisin jyväni ajallaan ja rypälemehuni määräaikanaan ja tempaan pois villani ja pellavani peittämästä hänen alastomuuttaan.',
        12: 'Nyt paljastan hänen häpynsä hänen rakastajiensa silmien eteen, eikä kukaan pelasta häntä kädestäni.',
        13: 'Teen lopun kaikesta hänen ilonpidostaan: hänen juhlistaan, uudenkuunjuhlistaan, sapateistaan ja kaikista hänen pyhäpäivistään.',
        14: "Hävitän hänen viiniköynnöksensä ja viikunapuunsa, joista hän on sanonut: 'Ne ovat portonpalkkani rakastajiltani.' Teen ne metsäksi, ja kedon eläimet syövät niitä.",
        15: 'Kostan hänelle baalien päivät, joina hän poltti niille uhreja, koristi itsensä renkaillaan ja kaulaketjuillaan ja kulki rakastajiensa perässä, mutta unohti minut, sanoo Herra.',
        16: 'Sen tähden, katso, minä taivuttelen häntä, vien hänet erämaahan ja puhun hänelle suloisesti.',
        17: 'Annan hänelle sieltä hänen viinitarhansa sekä Aakorin laakson toivon oveksi, ja hän on laulava siellä kuin nuoruutensa päivinä, kuin sinä päivänä, jona hän lähti Egyptin maasta.',
        18: "Sinä päivänä tapahtuu, sanoo Herra, että puhuttelet minua: 'Mieheni', etkä enää puhuttele minua: 'Baalini'.",
        19: 'Poistan baalien nimet hänen suustaan, eikä niiden nimiä enää muisteta.',
        20: 'Sinä päivänä teen heidän hyväkseen liiton kedon eläinten ja taivaan lintujen kanssa ja maan matelijoiden kanssa. Mutta jousen, miekan ja sodan särjen maasta ja annan heidän asua turvassa.',
        21: 'Kihlaan sinut itselleni ikiajoiksi, kihlaan sinut itselleni vanhurskaudella ja tuomiolla, armolla ja laupeudella,',
        22: 'kihlaan sinut itselleni uskon kautta, ja sinä olet tunteva Herran.',
        23: 'Sinä päivänä kuulen, sanoo Herra, kuulen taivasta, ja se kuulee maata,',
        24: 'ja maa kuulee jyviä, rypälemehua ja öljyä, ja nämä kuulevat Jisreeliä.',
        25: 'Kylvän hänet itselleni tähän maahan, armahdan Loo-Ruhamaa ja sanon Loo-Ammille: \'Sinä olet kansani\'; ja hän vastaa: \'Jumalani.\'"',
    },
    3: {
        1: 'Herra sanoi minulle: "Mene vielä ja rakasta naista, jota hänen puolisonsa rakastaa, mutta joka rikkoo avion, niin kuin Herra rakastaa israelilaisia, mutta nämä kääntyvät muiden jumalien puoleen ja rakastavat rypälekakkuja."',
        2: 'Ostin hänet itselleni viidellätoista sekelillä hopeaa sekä hoomer-mitalla ja letek-mitalla ohria',
        3: 'ja sanoin hänelle: "Ole kauan aikaa minua varten. Älä harjoita haureutta äläkä mene muille miehille. Minäkin teen samoin sinua kohtaan."',
        4: 'Sillä kauan aikaa saavat israelilaiset olla ilman kuningasta ja ruhtinasta, ilman uhria ja patsasta, ilman kasukkaa ja kotijumalia.',
        5: 'Sen jälkeen israelilaiset kääntyvät ja etsivät Herraa, Jumalaansa, ja Daavidia, kuningastaan. Vavisten he lähestyvät Herraa ja hänen hyvyyttään päivien lopulla.',
    },
    4: {
        1: 'Kuulkaa Herran sana, te israelilaiset, sillä Herralla on oikeudenkäynti maan asukkaiden kanssa. Maassa ei näet ole uskollisuutta, ei laupeutta eikä Jumalan tuntemusta.',
        2: 'Vannoskelu, valehtelu, murhat, varkaudet ja aviorikokset saavat vallan, ja verityö seuraa verityötä.',
        3: 'Sen tähden maa murehtii, ja kaikki sen asukkaat nääntyvät kedon eläinten ja taivaan lintujen kanssa. Kalatkin merestä kuolevat.',
        4: 'Älköön vain kukaan nuhdelko, älköön kukaan ojentako, vaikka kansasi on kuin pappien nuhtelijoita!',
        5: 'Kompastut päivällä, myös profeetta kompastuu kanssasi yöllä, ja hävitän äitisi.',
        6: 'Kansani joutuu häviöön tietoa vailla. Koska sinä olet hylännyt tiedon, hylkään sinut, niin ettet saa olla pappinani. Koska olet unohtanut Jumalasi lain, unohdan minäkin lapsesi.',
        7: 'Mitä enemmän heitä on, sitä enemmän he tekevät syntiä minua vastaan. Muutan heidän kunniansa häpeäksi.',
        8: 'Kansani synnistä he saavat ruokansa, heidän pahoja tekojaan heidän sielunsa himoitsee.',
        9: 'Mutta papin käy niin kuin kansankin. Rankaisen häntä hänen vaelluksestaan ja kostan hänelle hänen tekonsa.',
        10: 'He syövät, mutta eivät tule ravituiksi, he harjoittavat haureutta, mutta eivät lisäänny, sillä he eivät ole ottaneet vaarin Herrasta.',
        11: 'Haureus, viini ja rypälemehu vievät ymmärryksen.',
        12: 'Kansani kysyy puultaan, ja sen sauva vastaa sille. Sillä haureuden henki eksyttää. Haureudessa he ovat luopuneet Jumalastaan.',
        13: 'Vuorten huipuilla he uhraavat, polttavat uhreja kukkuloilla, rautatammen, poppelin ja tammen alla, sillä niiden varjo on suloinen. Sen tähden tyttäristänne tulee porttoja, ja miniänne rikkovat avion.',
        14: 'En rankaise tyttäriänne siitä, että he ovat porttoja, enkä miniöitänne siitä, että he rikkovat avion, sillä miehet itse poikkeavat syrjään porttojen kanssa ja uhraavat pyhäkköporttojen kanssa, ja ymmärtämätön kansa kukistuu.',
        15: 'Jos sinä, Israel, harjoitatkin haureutta, älköön Juuda saattako itseään syynalaiseksi. Älkää lähtekö Gilgaliin, älkää menkö ylös Beet-Aaveniin älkääkä vannoko: "Niin totta kuin Herra elää."',
        16: 'Sillä niin kuin niskuri lehmä on Israel niskoitellut. Nyt Herra on kaitseva heitä kuin karitsaa avaralla laitumella.',
        17: 'Efraim on liitossa epäjumalien kanssa – anna hänen olla.',
        18: 'Heidän juomansa on käynyt vastenmieliseksi. He harjoittavat törkeää haureutta. Ne, jotka ovat hänen kilpensä, rakastavat häpeää.',
        19: 'Tuuli siivillään ahdistaa häntä, ja he saavat häpeän uhreistaan.',
    },
    5: {
        1: 'Kuulkaa tämä, te papit, pankaa merkille, te Israelin heimo, ja ottakaa korviinne, te kuninkaan huone: teille on tämä tuomio. Sillä te olette olleet paula Mispalle, verkko, joka on levitetty Taaborille.',
        2: 'Luopiot ovat vajonneet syvälle turmioon, mutta minä olen kuritus heille kaikille.',
        3: 'Minä tunnen Efraimin, eikä Israel ole minulta piilossa. Sillä nyt sinä, Efraim, olet haureutta harjoittanut, Israel on itsensä saastuttanut.',
        4: 'Heidän tekonsa eivät salli heidän kääntyä heidän Jumalansa puoleen, sillä haureuden henki on heidän sisimmässään eivätkä he tunne Herraa.',
        5: 'Israelin ylpeys syyttää häntä vasten kasvoja, ja Israel ja Efraim kompastuvat syntivelkaansa. Myös Juuda kompastuu heidän kanssaan.',
        6: 'Lampaittensa ja nautojensa kanssa he tulevat etsimään Herraa, mutta eivät löydä. Hän on vetäytynyt heistä pois.',
        7: 'He ovat olleet uskottomia Herralle, sillä he ovat synnyttäneet vieraita lapsia. Nyt uudenkuun juhla syö heidät maineen.',
        8: 'Puhaltakaa torveen Gibeassa, trumpettiin Raamassa, nostakaa sotahuuto Beet-Aavenissa. Ovat jo kintereilläsi, Benjamin!',
        9: 'Efraim on tuleva autioksi kurituksen päivänä. Israelin heimokunnille olen ilmoittanut, mikä on totta.',
        10: 'Juudan ruhtinaat ovat tulleet rajansiirtäjien kaltaisiksi. Vuodatan heidän päälleen vihani kuin vedet.',
        11: 'Sorrettu on Efraim ja loukattu hänen oikeutensa, sillä hän tahtoi vaeltaa ihmiskäskyjen mukaan.',
        12: 'Mutta minä olen Efraimille kuin koi ja Juudan heimolle kuin mätä.',
        13: 'Mutta kun Efraim näki sairautensa ja Juuda haavansa, Efraim meni Assuriin, lähetti sanan suurkuninkaalle. Mutta tämä ei voinut teitä parantaa eikä tehdä terveeksi haavaanne.',
        14: 'Sillä minä olen Efraimille kuin leijona, Juudan heimolle kuin nuori leijona. Minä, minä raatelen, menen ja kannan pois, eikä pelastajaa ole.',
        15: 'Lähden ja palaan takaisin paikoilleni, kunnes he ovat tunnustaneet syyllisyytensä ja etsivät kasvojani. Ahdistuksessaan he etsivät minua.',
    },
    6: {
        1: 'Tulkaa, palatkaamme Herran tykö, sillä hän on raadellut meitä, mutta parantaa meidät, hän on lyönyt, mutta sitoo meidät.',
        2: 'Hän tekee meidät eläviksi kahden päivän kuluttua, kolmantena päivänä hän meidät herättää, ja me tulemme elämään hänen kasvojensa edessä.',
        3: 'Tuntekaamme, ahkeroikaamme tuntea Herra. Hänen ilmestymisensä on varma kuin aamurusko, hän tulee meille kuin sade, kuin kevätsade, joka kostuttaa maan.',
        4: 'Mitä minun on tehtävä sinulle, Efraim, mitä minun on tehtävä sinulle, Juuda, kun teidän laupeutenne on kuin aamun pilvi ja kuin varhain haihtuva kaste?',
        5: 'Sen tähden olen lyönyt heitä profeettojen kautta ja kuolettanut heitä suuni sanoilla, ja tuomiosi nousevat kuin valo.',
        6: 'Sillä haluan laupeutta enkä uhria, ja Jumalan tuntemista enemmän kuin polttouhreja,',
        7: 'mutta he ovat Aadamin tavoin rikkoneet liiton ja olleet siinä minulle uskottomia.',
        8: 'Gilead on pahantekijöiden kaupunki, täynnä veritahroja.',
        9: 'Väijyvän rosvojoukon kaltainen on pappien joukko. He murhaavat Sikemin tiellä ja tekevät häpeällisiä tekojaan.',
        10: 'Israelin huoneessa olen nähnyt kauhistuttavia tekoja. Siellä on Efraimin haureus, Israel on itsensä saastuttanut.',
        11: 'Myös sinua varten, Juuda, on asetettu elonkorjuu, silloin kun palautan kansani vankeudesta.',
    },
    7: {
        1: 'Kun parannan Israelia, silloin tulevat julki Efraimin rikokset ja Samarian pahuudet. Sillä he harjoittavat petosta, varas tulee sisään, ja rosvojoukko ryöstää ulkona.',
        2: 'He eivät sano sydämessään, että muistan kaiken heidän pahuutensa. Nyt heidän tekonsa piirittävät heidät, ne ovat kasvojeni edessä.',
        3: 'He ilahduttavat pahuudellaan kuningasta ja valheillaan ruhtinaita.',
        4: 'He ovat kaikki avionrikkojia. He ovat kuin leipojan lämmittämä uuni. Hän jättää tulen kohentamatta taikinan sotkemisesta sen happanemiseen asti.',
        5: 'Kuninkaamme päivänä ruhtinaat ovat sairaina viinin hehkusta. Hän lyö kättä pilkkaajien kanssa.',
        6: 'Sillä he ovat juonillaan saattaneet sydämensä kuumaksi kuin uuni. Koko yön heidän leipojansa nukkuu, aamulla se palaa kuin loimuava tuli.',
        7: 'He ovat kaikki kuumia kuin uuni. He syövät tuomarinsa. Kaikki heidän kuninkaansa ovat kaatuneet, eikä kukaan heistä ole huutanut minua avuksi.',
        8: 'Efraim sekoittuu kansojen joukkoon. Efraim on tullut leivän kaltaiseksi, jota ei ole käännetty.',
        9: 'Muukalaiset syövät hänen voimansa, mutta ei hän sitä ymmärrä. Hänen hiuksensakin ovat jo harmaantuneet, mutta hän ei ymmärrä.',
        10: 'Israelin ylpeys syyttää häntä vasten kasvoja. He eivät palaa Herran, Jumalansa, tykö eivätkä etsi häntä kaiken tämän tähden.',
        11: 'Efraim on tullut kyyhkysen kaltaiseksi, joka on tyhmä ja ymmärtämätön. He huutavat apuun Egyptiä ja menevät Assuriin.',
        12: 'Juuri kun he ovat menossa, heitän verkkoni heidän päälleen ja pudotan heidät alas kuin taivaan linnut. Kuritan heitä, niin kuin on julistettu heidän seurakunnalleen.',
        13: 'Voi heitä, sillä he ovat menneet minua pakoon! Häviö heille, sillä he ovat luopuneet minusta! Olen lunastanut heidät, mutta he puhuvat valheita minua vastaan.',
        14: 'He eivät huuda puoleeni sydämestään, vaan ulvovat vuoteissaan. Jyvien ja viinin tähden he kokoontuvat. Minua vastaan he niskoittelevat.',
        15: 'Minä olen heitä kurittanut, olen vahvistanut heidän käsivartensa, mutta minua vastaan he ovat aikoneet pahaa.',
        16: 'He kääntyvät, mutta eivät korkeutta kohti. He ovat kuin pettävä jousi. Heidän ruhtinaansa kaatuvat miekkaan kieltensä kiukkuisuuden tähden. Tämä koituu heille pilkaksi Egyptin maassa.',
    },
    8: {
        1: 'Aseta torvi suullesi! Kotkan lailla Herran huonetta vastaan – koska he ovat rikkoneet liittoni ja luopuneet laistani!',
        2: 'Minun puoleeni he huutavat: "Minun Jumalani!" – "Me Israel, tunnemme sinut."',
        3: 'Israel on hylännyt hyvän. Vihollinen sitä vainotkoon.',
        4: 'He ovat asettaneet kuninkaita, mutta se ei ole ollut minusta. He ovat asettaneet ruhtinaita, mutta en ole siitä tiennyt. Hopeansa ja kultansa he ovat tehneet epäjumalikseen, että tulisi hävitys.',
        5: 'Inhottava on vasikkasi, Samaria. Vihani on syttynyt heitä vastaan. Kuinka kauan he voivat olla rankaisematta.',
        6: 'Sillä se on Israelista ja seppä on sen tehnyt. Se ei ole jumala, vaan pirstaleiksi on menevä Samarian vasikka.',
        7: 'Sillä tuulta he ovat kylväneet, ja myrskyä he leikkaavat. Se ei anna satoa, laiho ei tuota jauhoja, ja minkä tuottaa, sen muukalaiset nielevät.',
        8: 'Nielty on Israel. He ovat nyt pakanoiden seassa kuin astia, joka ei kelpaa mihinkään.',
        9: 'Sillä Assuriin he ovat menneet kuin yksinäinen villiaasi. Efraim ostelee lahjoilla rakasteluja.',
        10: 'Vaikka he ovat ostelleet pakanoiden seassa, niin nyt heidät kokoan, ja he ovat alkaneet vähäksi aikaa kärsiä ruhtinaiden kuninkaan taakasta.',
        11: 'Koska Efraim on rakentanut paljon alttareita tehdäkseen syntiä, alttarit ovatkin tulleet hänelle synniksi.',
        12: 'Kirjoitinpa hänelle lakejani vaikka kymmeniä tuhansia, vieraina niitä pidetään.',
        13: 'Uhrilahjoikseni he uhraavat lihaa ja syövät. Herra ei niihin mielly. Nyt hän muistaa heidän rikoksensa ja rankaisee heidän syntinsä: Egyptiin on heidän palattava.',
        14: 'Israel on unohtanut tekijänsä ja rakentanut palatseja, ja Juuda on rakentanut paljon varustettuja kaupunkeja. Mutta lähetän tulen hänen kaupunkeihinsa, ja se kuluttaa niiden palatsit.',
    },
    9: {
        1: 'Israel, älä iloitse äläkä riemuitse, niin kuin muut kansat, sillä olet haureudessa luopunut Jumalastasi ja olet rakastanut portonpalkkoja kaikilla viljan puimatanterilla.',
        2: 'Puimatanner ja viinikuurna eivät heitä elätä, rypälemehu hänet pettää.',
        3: 'He eivät tule asumaan Herran maassa, vaan Efraimin on palattava Egyptiin, ja Assurissa he syövät saastaista.',
        4: 'He eivät vuodata viiniä juomauhriksi Herralle, eivätkä heidän teurasuhrinsa hänelle kelpaa. Ne ovat heille kuin murheen leipä. Kaikki, jotka sitä syövät, saastuttavat itsensä, sillä heidän leipänsä on heitä itseään varten. Se ei tule Herran temppeliin.',
        5: 'Mitä teette, kun tulee juhla-aika, Herran juhlapäivä?',
        6: 'Sillä katso, he menevät hävitystä pakoon. Egypti kokoaa heidät, ja Moof hautaa heidät. Orjantappurat valtaavat heidän hopeakalleutensa, ohdakkeita on oleva heidän teltoissaan.',
        7: 'Rangaistuksen päivät tulevat, koston päivät tulevat, Israel on sen tunteva. Hulluna on oleva profeetta, mieltä vailla hengen mies paljojen rikoksiesi ja suuren vihamielisyytesi tähden.',
        8: 'Efraim on väijyjä Jumalaani vastaan. Profeetta – hänen kaikilla teillään on pyydystäjän paula, ja vainoa on hänen Jumalansa huoneessa.',
        9: 'He ovat syvälle vajonneet turmiontekoon kuin Gibean päivinä. Hän muistaa heidän rikoksensa ja kostaa heidän syntinsä.',
        10: 'Kuin rypäleet erämaasta löysin Israelin. Kuin varhaishedelmät viikunapuussa sen alkurunsaudessa näin teidän isänne. He tulivat Baal-Peoriin, vihkiytyivät häpeäjumalalle ja tulivat kauhistaviksi, niin kuin heidän rakastettunsa.',
        11: 'Efraimilta lentää pois heidän kunniansa kuin lintu: ei synnyttämistä, ei raskautta, ei sikiämistä.',
        12: 'Vaikka he kasvattaisivat lapsensa isoiksi, teen heidät lapsettomiksi, niin ettei ihmisiä jää. Voi heitä itseänsäkin, kun heistä luovun!',
        13: 'Efraim on, kun katselen sitä Tyyroa kohti, istutettu laidunmaalle, mutta Efraim vie lapsensa surmaajalle.',
        14: 'Anna heille, Herra – mitä antaisitkaan? – anna heille hedelmätön kohtu ja kuivettuneet rinnat.',
        15: 'Kaikki heidän pahuutensa on Gilgalissa, sillä siellä vihastuin heihin. Heidän tekojensa pahuuden tähden karkotan heidät pois huoneestaan. En enää rakasta heitä. Kaikki heidän ruhtinaansa ovat niskureita.',
        16: 'Efraim on hakattu maahan, ja heidän juurensa on kuivettunut. Hedelmää he eivät tee. Jos synnyttävätkin, kuoletan heidän kohtunsa kalleimmat.',
        17: 'Jumalani on hylkäävä heidät, sillä he eivät ole häntä totelleet. He tulevat olemaan pakolaisia pakanoiden seassa.',
    },
    10: {
        1: 'Israel oli rehevä viiniköynnös, joka teki hedelmiä. Mitä runsaampi sen hedelmä oli, sitä enemmän se teki alttareita, ja mitä parempi sen maa oli, sitä parempia patsaita se pystytti.',
        2: 'Liukas oli heidän sydämensä. Nyt heitä siitä rangaistaan. Hän särkee heidän alttarinsa ja hävittää heidän patsaansa.',
        3: 'Sillä nyt he sanovat: "Meillä ei ole kuningasta, sillä emme ole pelänneet Herraa, ja mitä kuningas meille tekisi?"',
        4: 'He pitävät puheita, vannovat väärin ja tekevät liittoja, mutta tuomio versoo kuin myrkkyruoho pellon vaosta.',
        5: 'Beet-Aavenin vasikoiden tähden Samarian asukkaat joutuvat pelkoon. Sillä niiden tähden sen kansa murehtii ja myös papit, jotka ennen siitä iloitsivat, sen kunnian tähden, kun se on viety siltä pois.',
        6: 'Se itsekin viedään Assuriin lahjaksi suurkuninkaalle. Häpeän saa Efraim, ja häpeään joutuu Israel neuvoistaan.',
        7: 'Hukassa on Samaria kuninkaineen. Se on kuin lastu veden pinnalla.',
        8: 'Aavenin uhrikukkulat, Israelin synti, hävitetään. Orjantappuraa ja ohdaketta on kasvava heidän alttareillaan. Niin he sanovat vuorille: "Peittäkää meidät", ja kukkuloille: "Langetkaa päällemme."',
        9: 'Gibean päivistä asti olet, Israel, tehnyt syntiä. Sinne he ovat asettuneet. Eikö heitä Gibeassa saavuttaisi sota, sota vääryyden miehiä vastaan?',
        10: 'Haluni mukaan olen heitä kurittava, ja heitä vastaan kokoontuvat kansat, kun heidät sidotaan kiinni heidän kahteen rikokseensa.',
        11: 'Efraim on lehmä, joka on opetettu puimaan mielellään, mutta minä panen hänen kauniin kaulansa päälle ikeen. Valjastan Efraimin: Juuda kyntää, ja Jaakob äestää.',
        12: 'Kylväkää itsellenne vanhurskauden kylvö, niin saatte leikata laupeutta. Raivatkaa itsellenne uudispelto, sillä on aika etsiä Herraa, kunnes hän tulee ja antaa sataa teille vanhurskautta.',
        13: 'Te olette kyntäneet jumalattomuutta, korjanneet vääryyttä ja syöneet valheen hedelmää. Sillä olet luottanut omaan tiehesi ja sankariesi paljouteen.',
        14: 'Nousee pauhina kansojesi keskelle, ja kaikki linnoituksesi hävitetään, niin kuin Salman hävitti Beet-Arbelin sodan päivänä: äiti ruhjotaan lastensa päälle.',
        15: 'Tämän tekee teille Beetel ylenpalttisen pahuutenne tähden. Aamunkoitossa Israelin kuningas tuhoamalla tuhotaan.',
    },
    11: {
        1: 'Kun Israel oli nuori, minä rakastin häntä, ja Egyptistä minä kutsuin Poikani.',
        2: 'Kun he heitä kutsuivat, he menivät pois heidän kasvojensa edestä, uhrasivat baaleille ja polttivat uhreja epäjumalille.',
        3: 'Minä opetin Efraimin kävelemään. – Hän otti heidät käsivarsilleen. – Mutta he eivät ymmärtäneet, että paransin heidät.',
        4: 'Ihmissiteillä heitä vedin, rakkauden köysillä. Nostin ikään kuin ikeen heidän leukapieliltään, kumarruin heidän puoleensa ja syötin.',
        5: 'He eivät palaa Egyptin maalle, vaan Assur on heidän kuninkaansa, sillä he ovat kieltäytyneet kääntymästä.',
        6: 'Miekka on riehuva hänen kaupungeissaan. Se hävittää hänen salpansa ja syö ne heidän neuvojensa takia.',
        7: 'Kansani haluaa kääntyä minusta pois, ja vaikka sitä kutsutaan Korkeimman puoleen, kukaan heistä ei ylene.',
        8: 'Kuinka minä jättäisin sinut, Efraim, heittäisin sinut, Israel? Kuinka jättäisin sinut kuin Adman, tekisin sinulle kuin Seboimille? Sydämeni kääntyy, säälini herää.',
        9: 'En pane täytäntöön vihani hehkua enkä enää hävitä Efraimia. Sillä minä olen Jumala enkä ihminen, olen Pyhä keskelläsi. En tule kaupunkiin.',
        10: 'He vaeltavat Herran jäljessä. Hän ärjyy kuin leijona – niin, hän ärjyy, ja vavisten tulevat lapset lännestä.',
        11: 'Vavisten he tulevat Egyptistä kuin linnut, Assurin maasta kuin kyyhkyset, ja minä saatan heidät asumaan kodeissaan, sanoo Herra.',
    },
    12: {
        1: 'Efraim on ympäröinyt minut valheella ja Israelin huone vilpillä. Juuda juoksee yhä valtoimena, välittämättä Jumalasta, Pyhästä ja Totisesta.',
        2: 'Efraim ruokkii tuulta, ajaa takaa itätuulta ja kartuttaa kaiken aikaa valhetta ja hävitystä. Tehdään liittoja Assurin kanssa, ja viedään öljyä Egyptiin.',
        3: 'Mutta Herralla on oikeudenkäynti Juudan kanssa, ja hän on rankaiseva Jaakobille sen vaelluksen mukaan ja kostava sille sen tekojen mukaan.',
        4: 'Äidin kohdussa tämä petti veljensä, ja miehuutensa voimassa hän taisteli Jumalan kanssa.',
        5: 'Hän taisteli Enkelin kanssa ja voitti, hän itki ja rukoili tätä. Beetelissä tämä löysi hänet ja puhui siellä kanssamme.',
        6: 'Herra, Jumala Sebaot – Herra on hänen nimensä.',
        7: 'Mutta sinä – käänny Jumalasi tykö, noudata laupeutta ja oikeutta ja pane alati toivosi Jumalaasi.',
        8: 'Kanaan – hänen kädessään on petollinen vaaka, ja hän rakastaa sortoa.',
        9: 'Efraim sanoo: "Olen rikastunut, olen saanut itselleni omaisuutta, enkä havaitse teoissani vääryyttä, joka olisi syntiä."',
        10: 'Mutta minä, joka olen Herra, Jumalasi, Egyptin maasta lähtien, saatan sinut vielä asumaan teltoissa kuin juhlapäivinä. Hoos',
        11: 'Olen puhunut profeetoille, minä olen antanut paljon näkyjä ja puhunut vertauksia profeettojen kautta.',
        12: 'Jos Gilead onkin ollut pelkkää petosta, niin he tulevat pelkäksi turhuudeksi. Gilgalissa on uhrattu härkiä, niinpä heidän alttareistaan tulee kuin kivikasoja, joita on pellon vaoilla.',
        13: 'Jaakob pakeni Aramin kedoille, ja Israel palveli naisen tähden, naisen tähden hän paimensi.',
        14: 'Mutta profeetan kautta Herra vei Israelin pois Egyptistä, ja profeetta sitä paimensi.',
        15: 'Efraim vihastutti Herran katkerasti, ja sen vuoksi hänen verivelkansa jäävät hänen päälleen ja Herra kääntää hänen häpäisevän pilkkansa häneen itseensä.',
    },
    13: {
        1: 'Kun Efraim puhui, syntyi kauhu. Hän kohosi korkealle Israelissa, mutta hän tuli syynalaiseksi Baalin takia ja kuoli.',
        2: 'Nyt he jatkavat synnintekoa, tekevät itselleen valettuja kuvia hopeastaan, epäjumalankuvia ymmärryksensä mukaan, seppien tekemiä kaikki. Niille he puhuvat, teurastavat ihmisiä ja suutelevat vasikoita.',
        3: 'Sen tähden he ovat kuin aamun pilvi, kuin kaste, joka haihtuu varhain, kuin akanat, jotka tuuli vie puimatantereelta kuin savun ikkunasta.',
        4: 'Mutta minä olen Herra, Jumalasi, hamasta Egyptin maasta lähtien. Muuta Jumalaa et tunne kuin minut, eikä ole muuta Vapahtajaa kuin minä.',
        5: 'Minä tunsin sinut erämaassa, kuivassa maassa.',
        6: 'Laidunmaittensa mukaan he tulivat kylläisiksi. He tulivat kylläisiksi, ja heidän sydämensä tuli ylpeäksi, ja sen tähden he unohtivat minut.',
        7: 'Sen tähden tulen olemaan heille kuin leijona, kuin leopardi väijyn heitä tien varressa.',
        8: 'Käyn heidän kimppuunsa kuin karhu, jolta on riistetty poikaset, revin heidän sydänkalvonsa ja syön heidät siinä paikassa kuin naarasleijona. Kedon pedot raatelevat heidät.',
        9: 'Israel, se on tuhosi, että olet minua vastaan, joka olen apusi.',
        10: 'Missä on nyt kuninkaasi, että hän auttaisi sinua kaikissa kaupungeissasi, ja tuomarisi, joista olet sanonut: "Anna minulle kuningas ja ruhtinaat"?',
        11: 'Kuninkaan annoin sinulle vihassani ja otin pois kiivastuksessani.',
        12: 'Efraimin rikos on sidottu kokoon, talteen on pantu hänen syntinsä.',
        13: 'Hänelle tulevat synnyttäjän tuskat. Hän on älytön lapsi, sillä hän ei tule ajallaan kohdusta esiin.',
        14: 'Helvetin kädestä heidät pelastan, kuolemasta heidät lunastan. Missä on sinun ruttosi, kuolema, missä sinun surmasi, helvetti? Katumus on peitetty silmiltäni.',
        15: 'Vaikka hän on veljien keskellä hedelmällinen, itätuuli tulee, Herran tuuli nousee erämaasta, ja hänen kaivonsa kuivuu ja lähteensä ehtyy: se ryöstää hänen aarteensa, kaikki hänen kallisarvoiset esineensä.',
    },
    14: {
        1: 'Samaria hävitetään, koska se on noussut Jumalaansa vastaan: he kaatuvat miekkaan, heidän pienet lapsensa ruhjotaan, ja heidän raskaana olevat vaimonsa halkaistaan.',
        2: 'Palaa, Israel, Herran, Jumalasi, tykö, sillä olet kompastunut rikoksiisi.',
        3: 'Ottakaa mukaanne sanoja ja palatkaa Herran tykö ja sanokaa hänelle: "Anna anteeksi kaikki rikokset, ota armoihisi, niin tuomme sinulle uhrimulleiksi huultemme uhrit.',
        4: 'Assur ei meitä pelasta, hevosilla emme ratsasta emmekä enää sano kättemme teoille: \'Meidän jumalamme\'; sillä sinulta orpo löytää armon."',
        5: 'Parannan luopumuksenne, rakastan heitä tahtoni mukaan, sillä vihani on kääntynyt heistä pois.',
        6: 'Olen oleva Israelille kuin kaste. Se on kukoistava kuin lilja ja juurtuva syvälle kuin Libanon.',
        7: 'Sen vesat leviävät, sen kauneus on oleva kuin öljypuun ja sen tuoksu kuin Libanonin.',
        8: 'Sen varjossa asuvat kasvattavat jälleen viljaa ja kukoistavat kuin viiniköynnös. Sen maine on oleva kuin Libanonin viinin.',
        9: 'Efraim! Mitä on minulla enää tekemistä epäjumalien kanssa? Minä kuulen häntä ja katson hänen puoleensa, minä, joka olen kuin viheriöivä sypressi: minusta on hedelmäsi.',
        10: 'Kuka on viisas ja nämä ymmärtää? Kuka osaa ja tuntee nämä? Sillä Herran tiet ovat suorat, vanhurskaat niillä vaeltavat, mutta luopiot niillä kompastuvat.',
    },
}
